#include "resource/qrx_storage_atlas.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
int main(void){QrxStorageAtlasProvider p[8];memset(p,0,sizeof(p));for(int i=0;i<8;i++){snprintf(p[i].provider_id,sizeof(p[i].provider_id),"p%d",i);strcpy(p[i].region,i<6?"southern-africa":"europe-west");snprintf(p[i].asn,sizeof(p[i].asn),"AS%d",i);p[i].network_attested=1;strcpy(p[i].capacity.provider_id,p[i].provider_id);p[i].capacity.configured_bytes=1000;p[i].capacity.physical_eligible_bytes=1000;p[i].capacity.proven_bytes=1000;p[i].capacity.allocated_physical_bytes=i<6?800:100;p[i].capacity.availability_bps=9900;p[i].capacity.proof_success_bps=9950;}QrxStorageAtlasCell *c=NULL;size_t n=0;assert(qrx_storage_atlas_build(p,8,5,&c,&n)==0&&n==2);int seen=0;for(size_t i=0;i<n;i++)if(!strcmp(c[i].region,"southern-africa")){assert(c[i].publicly_visible);assert(c[i].provider_count==6);assert(c[i].opportunity_score>0);seen=1;}else assert(!c[i].publicly_visible);assert(seen);QrxStorageMission *m=NULL;size_t mn=0;assert(qrx_storage_missions_from_atlas(c,n,5000,10,&m,&mn)==0&&mn>=1);assert(m[0].incentive_factor_bps<=12000);QrxStorageProviderCapacity pc[2];memset(pc,0,sizeof(pc));for(int i=0;i<2;i++){strcpy(pc[i].provider_id,"x");pc[i].configured_bytes=1000;pc[i].physical_eligible_bytes=1000;pc[i].proven_bytes=1000;pc[i].allocated_physical_bytes=700;}QrxStorageNetworkCapacity net;assert(qrx_storage_capacity_aggregate(pc,2,1000,14,0,0,qrx_storage_profile_by_name("STANDARD"),&net)==0);assert(qrx_storage_dynamic_demand_factor_bps(&net)>=8000&&qrx_storage_dynamic_demand_factor_bps(&net)<=15000);assert(qrx_storage_network_health_score(&net,9900,8000)<=100);qrx_storage_missions_free(m);qrx_storage_atlas_free(c);return 0;}
